    'cf.title': {ru: 'Цветные фильтры — размечаются в каждой открытой статье, пока их не очистить', en: 'Colour filters — marked in every article you open until cleared', de: 'Farbfilter — in jedem geöffneten Artikel markiert, bis sie gelöscht werden', fr: "Filtres de couleur — marqués dans chaque article ouvert jusqu’à ce qu’on les efface"},
    'cf.ph': {ru: 'слово, маска, "фраза"', en: 'word, mask, "phrase"', de: 'Wort, Maske, "Phrase"', fr: "mot, masque, \"expression\""},
