    'view.textonly': {ru: 'только текст (без списка лемм и колонки)', en: 'text only (no lemma list, no side column)', de: 'nur Text (ohne Lemmaliste und Randspalte)', fr: "texte seul (sans liste des lemmes ni colonne latérale)"},
