    'work.note_ph': {ru: 'Текст заметки. Выделенное в статье добавляется сюда кнопкой ✎ вместе со ссылкой на том и колонку.', en: 'The text of the note. What you select in an article is added here with ✎, together with volume and column.', de: 'Text der Notiz. Im Artikel Markiertes wird mit ✎ samt Band und Spalte hier angefügt.', fr: "Le texte de la note. Ce que vous sélectionnez dans un article s’ajoute ici avec ✎, avec le volume et la colonne."},
    'work.note_hint': {ru: 'Сохраняется сама при каждом изменении.', en: 'Saved by itself at every change.', de: 'Wird bei jeder Änderung selbst gespeichert.', fr: "Enregistré automatiquement à chaque modification."},
